mapper.select:
SELECT `id`, `guid`, `user_identifier` AS userIdentifier, `bucket_name` AS bucketName, `volume_guid` AS volumeGuid, `ext_config` AS extConfig, `create_time` AS createTime, `update_time` AS updateTime
FROM `hydra_uofs_bucket`


    AND `user_identifier` = #{userIdentifier}


    AND `bucket_name` = #{bucketName}


ORDER BY `create_time` DESC
LIMIT #{limit} OFFSET #{offset}
